import { useMemo, useCallback } from "react";

import { type AttachmentHandlerOpts, type MessageAttachment } from "@sierra/web";

export function useAttachmentHandlerChaining(
    types: string[],
    attachments: MessageAttachment[],
    opts: AttachmentHandlerOpts
) {
    const [handledAttachments, unhandledAttachments] = useMemo(() => {
        const handled: MessageAttachment[] = [];
        const unhandled: MessageAttachment[] = [];
        attachments.forEach(attachment => {
            const data = JSON.parse(attachment.data) as { type: string };
            if (types.includes(data.type)) {
                handled.push(attachment);
            } else {
                unhandled.push(attachment);
            }
        });

        return [handled, unhandled] as const;
    }, [attachments, types]);

    const renderUnhandled = useCallback(
        (ref: HTMLElement | null) => {
            if (ref) {
                opts.nextHandler?.(unhandledAttachments, { ...opts, containerElement: ref });
            }
        },
        [opts, unhandledAttachments]
    );

    return [
        handledAttachments,
        unhandledAttachments.length > 0 ? <div ref={renderUnhandled} /> : null,
    ] as const;
}
